const r = await tools.mcp__codex_apps__lobu_run_sdk({
  timeout_ms:180000,
  script:`export default async (_ctx, client) => {
  const connection_id = 432;
  const available = await client.operations.listAvailable({ connection_id });
  const nav = await client.operations.execute({
    connection_id,
    operation_key: "navigate",
    input: { url: "https://buremba.lobu.ai/", open_in_new_tab: true, wait_for_load: true }
  });
  const tab_id = nav.output?.tab_id;
  if (!tab_id) return { available, nav };
  try {
    const inspected = await client.operations.execute({
      connection_id,
      operation_key: "evaluate",
      input: {
        tab_id,
        await_promise: true,
        expression: \`(async () => {
          await new Promise(r => setTimeout(r, 2500));
          return {
            url: location.href,
            title: document.title,
            readyState: document.readyState,
            headings: [...document.querySelectorAll("h1,h2,h3,[role=heading]")].map(x => (x.textContent || "").trim()).filter(Boolean),
            buttons: [...document.querySelectorAll("button")].map(x => (x.textContent || "").trim()).filter(Boolean).slice(0, 40),
            selects: [...document.querySelectorAll("[role=combobox],select")].map(x => ({
              text: (x.textContent || "").trim(),
              aria: x.getAttribute("aria-label")
            })),
            bodyText: (document.body.innerText || "").slice(0, 12000),
            rootHtml: document.querySelector("#root")?.innerHTML.slice(0, 20000) || ""
          };
        })()\`
      }
    });
    return { available, nav, inspected };
  } finally {
    await client.operations.execute({
      connection_id,
      operation_key: "close_tab",
      input: { tab_id }
    });
  }
}`
});
for (const c of (r?.content ?? [])) if (c.type === "text") text(c.text);

