+/**
+ * Recent activity across every agent in a workspace. `scope=all` is the
+ * server's consolidated, materialized listing: app/API chats, platform
+ * conversations (Slack, Telegram, and any other connector), and Behavior
+ * activity all arrive through the same contract.
+ */
+export function useRecentAgentThreads(
+	orgSlug?: string | null,
+	agentIds?: string[],
+	options?: { enabled?: boolean; limit?: number },
+) {
+	const limit = options?.limit ?? 8;
+	const enabled =
+		!!orgSlug && (agentIds?.length ?? 0) > 0 && (options?.enabled ?? true);
+
+	const queries = useQueries({
+		queries: (agentIds ?? []).map((agentId) => ({
+			...agentThreadsQueryOptions(orgSlug, agentId, {
+				strict: false,
+				scope: "all",
+			}),
+			enabled,
+		})),
+	});
+
+	const isLoading = enabled && queries.some((query) => query.isLoading);
+	const threads = queries
+		.flatMap((query, index) => {
+			const agentId = agentIds?.[index];
+			if (!agentId) return [];
+			return (query.data ?? []).map((thread) => ({ agentId, ...thread }));
+		})
+		.sort((a, b) => b.updatedAt - a.updatedAt)
+		.slice(0, limit);
+
+	return { threads, isLoading };
+}
